local item_lib = require("items")

function event_say(e)
  if e.message:findi("hail") then
    e.self:Say("Hail! I long to speak with a minstrel. I am curious about what has gone on beyond our borders here. Are you a bard? If not then I have no use for you.")
  end
  if e.message:findi("i am a bard") then
    e.self:Say("So troubadour, what news and stories have you from the New World? Oh, I forget my manners. We shall exchange talk another time. You seek something do you not? A new outfit perhaps?")
  end
  if e.message:findi("i seek a new outfit") then
    e.self:Say("Well then, I have just what you need. Now, my terms of\npayment is thus, you gather some things for me and in return I shall craft you the finest armor a bard has ever seen! A new outfit comprised of a helm, breastplate, armplates, bracers, gauntlets, greaves, and boots shall make you the envy of your peers, my little friend.")
  end
  if e.message:findi("helm") then
    e.self:Say("A brand new shiny helm shall be yours once I have an ancient tarnished plate helmet and three pieces of crushed coral. May the audience swoon in your presence.")
  end
  if e.message:findi("breastplate") then
    e.self:Say("I have need of an ancient tarnished breastplate and three\nflawless diamonds. Find these for me and I shall craft you a breastplate, minstrel. May it protect you from unruly audiences with rotten vegetables.")
  end
  if e.message:findi("armplate") then
    e.self:Say("A gorgeous pair of armplates shall be yours once you have\nretrieved a pair of ancient tarnished plate vambraces and three flawed emeralds. The detail and craftsmanship is stunning!")
  end
  if e.message:findi("bracer") then
    e.self:Say("A pair of bracers shall be yours upon receipt of an ancient\ntarnished plate bracer and three crushed flame emeralds. May your songs never\nfalter during a tactical retreat.")
  end
  if e.message:findi("gauntlet") then
    e.self:Say("It would be a shame if your hands were to be injured and not be able to play your instruments wouldn't it? I shall craft some gauntlets so that your nimble digits remain intact. Bring me a pair of ancient tarnished plate gauntlets as well as three crushed topaz.")
  end
  if e.message:findi("greaves") then
    e.self:Say("Some new greaves would do you some good. The pair you have now looks quite stained and worn. Nevermind, fetch me a pair of ancient tarnished plate greaves and three flawed sea sapphires.")
  end
  if e.message:findi("boots") then
    e.self:Say("A fancy pair of boots you want is it? Yes, I can see the pair you have now looks a bit worn from running so much. All I require is a set of three crushed pieces of black marble and a pair of ancient tarnished plate boots.")
  end
end

